reproduction.emitterBuild:
//! Development probe of the public Agent compiler against a frozen Boundary delta.
const std = @import("std");
pub fn build(b: *std.Build) void {
    const boundary_root = b.option([]const u8, "boundary-source", "Frozen candidate Boundary") orelse @panic("boundary-source");
    const agent_root = b.option([]const u8, "agent-source", "Frozen Agent") orelse @panic("agent-source");
    const data = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary_root, "src/v2/data/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe });
    const boundary = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary_root, "src/v2/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = "boundary_data", .module = data }} });
    const contracts = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent_root, "src/contracts.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = "boundary_data", .module = data }} });
    const agent = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent_root, "src/agent4.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{ .{ .name = "boundary", .module = boundary }, .{ .name = "boundary_data", .module = data }, .{ .name = "agent_contracts", .module = contracts } } });
    const root = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent_root, "test/consumers/inquiry/main.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{ .{ .name = "agent", .module = agent }, .{ .name = "boundary", .module = boundary } } });
    b.installArtifact(b.addExecutable(.{ .name = "inquiry-emitter", .root_module = root }));
}

