import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {semantic,rows} from '$PRIOR_EXPERIMENT_ROOT/compare.mjs';
const d=import.meta.dirname, prev='$PRIOR_EXPERIMENT_ROOT', inputs=JSON.parse(readFileSync(prev+'/inputs.json'));
const qualified=new Map(JSON.parse(readFileSync(prev+'/semantic-qualification.json')).map(x=>[x.lane,x.semantic]));
const lanes={application:'inquiry_application_runtime.mjs',cases:'inquiry_cases_runtime.mjs',repeated:'inquiry_repeated_runtime.mjs'};
const formats=['bpc1','unpruned','pruned'];const all=[];
mkdirSync(d+'/measurements',{recursive:true});
for(let window=0;window<2;window++)for(let round=0;round<3;round++)for(const[lane,file]of Object.entries(lanes))for(let offset=0;offset<3;offset++){
 const format=formats[(window+round+offset)%3],old=format==='bpc1',key=old?'before':'after',driver=old?'bpc1':'bpi3',id=`w${window}-r${round}-${lane}-${format}`;
 const fixtures=format==='pruned'?d+'/fixtures-pruned':prev+'/fixtures-'+driver;
 const args=[prev+'/drivers-'+driver+'/'+file,inputs[key].runtime,fixtures,prev+'/tools-'+key+'/bin/native',prev+'/tools-'+key+'/bin/inspector',...(lane==='cases'?['--comparison-only']:[])];
 const started=process.hrtime.bigint(),result=spawnSync(process.execPath,args,{maxBuffer:16<<20,timeout:300000});
 const processNanoseconds=Number(process.hrtime.bigint()-started);
 writeFileSync(d+'/measurements/'+id+'.log',result.stderr??Buffer.alloc(0));assert.equal(result.status,0,id+': '+result.stderr?.toString());
 const evidence=JSON.parse(result.stdout);assert.deepEqual(semantic(evidence,lane),qualified.get(lane),id+': semantic/work-count drift');
 writeFileSync(d+'/measurements/'+id+'.json',JSON.stringify(evidence,null,2)+'\n');
 all.push({window,round,lane,format,processNanoseconds,rows:rows(evidence,lane)});
 writeFileSync(d+'/observations.json',JSON.stringify({method:'Three rotating observations per lane/format/window, two windows. Only compiled catalogue closure differs between current variants; the World kernel, native tools and Agent policies are identical. Original guest interval and semantic assertions are retained.',observations:all},null,2)+'\n');
 console.log(JSON.stringify({completed:all.length,total:54,window,round,lane,format,seconds:processNanoseconds/1e9}));
}

preparationDiagnostic.driver:
const std = @import("std");
const world = @import("world");
const Budget = world.AllocationBudget;
pub fn main(init: std.process.Init) !void {
    var args = init.minimal.args.iterate();
    _ = args.next();
    const path = args.next() orelse return error.MissingImage;
    const image = try std.Io.Dir.cwd().readFileAlloc(init.io, path, init.gpa, .limited(64 << 20));
    defer init.gpa.free(image);
    var budget: Budget = .{ .parent = init.gpa, .limit = 128 << 20 };
    var prepared = try world.Prepared.init(budget.allocator(), image);
    std.debug.print("prepared live={d} peak={d} reported={d}\n", .{budget.live, budget.peak, try prepared.storageBytes()});
    prepared.deinit();
    std.debug.assert(budget.live == 0);
}

