const std = @import("std");
pub fn build(b: *std.Build) void {
    const boundary = b.option([]const u8, "boundary-source", "Diagnostic Boundary") orelse @panic("boundary-source");
    const world = b.option([]const u8, "world-source", "Frozen World") orelse @panic("world-source");
    const data = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{boundary,"src/v2/data/root.zig"}) }, .target=b.graph.host, .optimize=.ReleaseSafe });
    const runtime = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{world,"src/root.zig"}) }, .target=b.graph.host, .optimize=.ReleaseSafe, .imports=&.{.{.name="boundary_data",.module=data}} });
    const main = b.createModule(.{ .root_source_file=b.path("profile.zig"), .target=b.graph.host, .optimize=.ReleaseSafe, .imports=&.{.{.name="world",.module=runtime}} });
    b.installArtifact(b.addExecutable(.{.name="profile",.root_module=main}));
}
